"""Independent Python outcomes for the reviewer semantic-rule witnesses."""


def filter_false(s):
    return s.swapcase() if any(c.isalpha() for c in s if False) else s[::-1]


def swapcase_arg(s):
    return s.swapcase(1)


print("filter_false input='a' python_result=", repr(filter_false("a")))
